    useEffect(() => {
        const checkAuth = async () => {
            try {
                await getUser();
            } catch (error) {
                router.push("/login");
            } finally {
                setCheckingAuth(false);
            }
        };

        checkAuth();
    }, [router]);

    useEffect(() => {
        const loadFeatured = async () => {
            try {
                const res = await getFeaturedCourts();
                setFeaturedCourts(res.data || []);
            } catch (error) {
                setFeaturedCourts([]);
            }
        };

        loadFeatured();
    }, []);

    if (checkingAuth) {
        return (
